<template>
  <ion-page class="review-page">
    <AppHeader variant="admin" title="Tinjau SPK" :show-back="true" />
    <ion-content :fullscreen="true">
      <main class="review-shell">
        <div v-if="loading" class="review-state"><ion-spinner name="crescent" /><p>Memuat data SPK...</p></div>
        <div v-else-if="errorMessage" class="review-state review-error" role="alert"><strong>Data tidak dapat dimuat</strong><p>{{ errorMessage }}</p><AppButton size="small" @click="load">Coba lagi</AppButton></div>
        <template v-else-if="data">
          <header class="review-heading"><div><p class="eyebrow">Administrasi SPK</p><h1>{{ data.request.spk_number }}</h1><span class="status-chip">Approved</span></div><span class="review-id">SPK #{{ data.request.id }} · Transaksi #{{ data.transaction.id }}</span></header>
          <section class="review-panel"><h2>Informasi SPK</h2><dl class="info-grid">
            <div><dt>Customer</dt><dd>{{ data.request.customer_full_name }}</dd></div><div><dt>Nomor telepon</dt><dd>{{ data.request.customer_phone }}</dd></div><div><dt>Kavling</dt><dd>{{ data.request.lots?.lot_number || data.request.lot_id }}</dd></div><div><dt>Harga transaksi</dt><dd>{{ money(data.request.lot_price_snapshot) }}</dd></div><div><dt>Metode pembayaran</dt><dd>{{ data.request.payment_method === 'Cash' ? 'Tunai' : 'Cicilan' }}</dd></div><div><dt>Booking Fee</dt><dd>{{ money(data.request.booking_fee_snapshot) }}</dd></div><div><dt>Tanggal persetujuan</dt><dd>{{ date(data.request.approved_at) }}</dd></div><div><dt>Marketing</dt><dd>{{ data.request.profiles?.full_name || 'Tidak ada' }}</dd></div><div><dt>Sumber pengajuan</dt><dd>{{ data.request.submission_source }}</dd></div>
          </dl></section>
          <section class="review-panel"><div class="section-head"><div><h2>Jadwal pembayaran</h2><p v-if="!data.schedules.length">Tidak ada jadwal cicilan untuk transaksi ini.</p></div></div><div v-if="data.schedules.length" class="schedule-list"><div v-for="item in data.schedules" :key="item.id" class="schedule-row"><span>Cicilan {{ item.installment_number }}</span><strong>{{ money(item.amount) }}</strong><input v-model="item.due_date" type="date" :disabled="item.status === 'Paid'" :aria-label="`Jatuh tempo cicilan ${item.installment_number}`" @change="saveSchedule(item)" /><span :class="['payment-status', item.status === 'Paid' ? 'paid' : 'pending']">{{ item.status === 'Paid' ? 'Confirmed' : item.status }}</span></div></div></section>
          <section v-if="data.commission" class="review-panel"><h2>Komisi Marketing</h2><dl class="info-grid"><div><dt>Nama marketing</dt><dd>{{ data.commission.profiles?.full_name || data.request.profiles?.full_name }}</dd></div><div><dt>Nomor SPK</dt><dd>{{ data.request.spk_number }}</dd></div><div><dt>Nilai transaksi</dt><dd>{{ money(data.commission.base_amount) }}</dd></div><div><dt>Jenis komisi</dt><dd>{{ data.commission.commission_type }}</dd></div><div><dt>Persentase / nominal</dt><dd>{{ data.commission.commission_rate != null ? `${data.commission.commission_rate}%` : money(data.commission.commission_amount) }}</dd></div><div><dt>Total komisi</dt><dd>{{ money(data.commission.commission_amount) }}</dd></div><div><dt>Status pencairan</dt><dd>{{ data.commission.status }}</dd></div></dl></section>
          <section class="review-panel"><div class="section-head"><div><h2>Monitoring pengurusan SPK</h2><p>Status terpisah dari persetujuan SPK.</p></div><AppButton size="small" @click="progressOpen = true">Perbarui status</AppButton></div><div class="timeline"><div v-for="(item, index) in timeline" :key="item.id || index" class="timeline-item" :class="{ current: index === 0 }"><span class="timeline-dot" aria-hidden="true" /><div><strong>{{ item.new_status || item.status }}</strong><small>{{ date(item.created_at) }} · {{ item.profiles?.full_name || 'Admin' }}</small><p v-if="item.note">{{ item.note }}</p></div></div></div></section>
        </template>
      </main>
    </ion-content>
    <AppModal v-model="progressOpen" title="Perbarui progres SPK" variant="bottom-sheet" :loading="saving" @confirm="saveProgress"><label class="modal-field">Status baru<select v-model="progressStatus"><option v-for="status in statuses" :key="status" :value="status">{{ status }}</option></select></label><label class="modal-field">Catatan<textarea v-model="progressNote" rows="3" placeholder="Catatan perubahan (opsional)" /></label></AppModal>
  </ion-page>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { IonContent, IonPage, IonSpinner } from '@ionic/vue'
import AppHeader from '@/components/common/AppHeader.vue'; import AppButton from '@/components/ui/AppButton.vue'; import AppModal from '@/components/ui/AppModal.vue'
import { getSPKReview, updateInstallmentSchedule, updateNotaryProgress, type NotaryStatus } from '@/services/Admin/spkReviewService'
const route = useRoute(); const loading = ref(true); const saving = ref(false); const errorMessage = ref(''); const data = ref<any>(null); const progressOpen = ref(false); const progressNote = ref(''); const statuses: NotaryStatus[] = ['Diproses', 'Proses Notaris', 'Penandatanganan Notaris', 'Selesai']; const progressStatus = ref<NotaryStatus>('Diproses')
const timeline = computed(() => data.value?.history || [])
const money = (n: number | null) => n == null ? '-' : new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(n))
const date = (v: string | null) => v ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(v)) : '-'
async function load() { loading.value = true; errorMessage.value = ''; try { data.value = await getSPKReview(Number(route.params.spkId), Number(route.query.transactionId)); progressStatus.value = data.value.request.notary_status || 'Diproses' } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Terjadi kesalahan.' } finally { loading.value = false } }
async function saveSchedule(item: any) { try { await updateInstallmentSchedule(Number(item.id), item.due_date) } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Jadwal gagal diperbarui.'; await load() } }
async function saveProgress() { saving.value = true; try { await updateNotaryProgress(Number(route.params.spkId), progressStatus.value, progressNote.value); progressOpen.value = false; progressNote.value = ''; await load() } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Status gagal diperbarui.' } finally { saving.value = false } }
onMounted(load)
</script>
<style scoped>
.review-page { --review-gap: 16px; font-family: var(--font-primary); } .review-shell { max-width: 1100px; margin: 0 auto; padding: 24px 16px calc(96px + env(safe-area-inset-bottom)); color: var(--text-primary); } .review-heading,.section-head { display:flex; justify-content:space-between; gap:16px; align-items:flex-start; } .eyebrow { margin:0 0 4px; color:var(--poliland-gold-text); font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.08em; } h1 { margin:0; font-size:clamp(24px,5vw,36px); } h2 { margin:0 0 16px; font-size:18px; } .review-id { color:var(--text-secondary); font-size:13px; } .status-chip,.payment-status { display:inline-flex; padding:6px 10px; border-radius:var(--radius-control); background:var(--status-success-bg); color:var(--poliland-green); font-weight:700; font-size:12px; } .review-panel { margin-top:var(--review-gap); padding:20px; background:var(--surface-primary); border:1px solid var(--border-default); border-radius:var(--radius-panel); } .info-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:16px; margin:0; } dt { color:var(--text-secondary); font-size:12px; } dd { margin:4px 0 0; font-weight:600; overflow-wrap:anywhere; } .schedule-list { display:grid; gap:8px; } .schedule-row { display:grid; grid-template-columns:1fr auto minmax(140px,180px) auto; gap:12px; align-items:center; padding:12px; background:var(--surface-muted); border-radius:var(--radius-control); } input,select,textarea { min-height:44px; border:1px solid var(--border-default); border-radius:var(--radius-control); padding:10px; color:var(--text-primary); background:var(--surface-primary); font:inherit; } .timeline { display:grid; gap:18px; } .timeline-item { display:grid; grid-template-columns:16px 1fr; gap:12px; position:relative; } .timeline-item:not(:last-child)::after { content:''; position:absolute; left:7px; top:18px; bottom:-20px; width:2px; background:var(--border-default); } .timeline-dot { width:14px; height:14px; border-radius:50%; background:var(--border-default); margin-top:3px; } .timeline-item.current .timeline-dot { background:var(--poliland-green); } .timeline-item small { display:block; color:var(--text-secondary); margin-top:4px; } .timeline-item p { margin:6px 0 0; } .review-state { display:grid; place-items:center; gap:8px; min-height:40vh; text-align:center; } .review-error { color:var(--status-danger); } .modal-field { display:grid; gap:6px; margin-bottom:16px; } .modal-field select,.modal-field textarea { width:100%; } button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible { outline:3px solid color-mix(in srgb,var(--poliland-green) 45%, transparent); outline-offset:2px; }
@media (max-width: 760px) { .review-shell { padding-top:16px; } .review-heading { display:block; } .review-id { display:block; margin-top:8px; } .info-grid { grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px 12px; } .schedule-row { grid-template-columns:1fr auto; } .schedule-row input { grid-column:1 / -1; width:100%; } }
@media (max-width: 480px) { .info-grid { grid-template-columns:1fr; } .review-panel { padding:16px; border-radius:var(--radius-card); } }
</style>
